static NbnxmKernelFunc* selectNbnxmKernelNoenerEspSimd2xmm(const int coulkt, const int vdwkt, const int forceOrder)
{
    const int coulombIndex = nbnxmEspAnalyticalCoulombKernelIndex2xmm(coulkt);
    if (coulombIndex < 0)
    {
        return nbnxmKernelNoenerSimd2xmm[coulkt][vdwkt];
    }
    if (forceOrder >= c_nbnxmEspSpecializedForceOrderMin2xmm
        && forceOrder <= c_nbnxmEspSpecializedForceOrderMax2xmm)
    {
        return nbnxmKernelNoenerEspForceOrderSimd2xmm[coulombIndex][forceOrder - c_nbnxmEspSpecializedForceOrderMin2xmm][vdwkt];
    }
    return nbnxmKernelNoenerEspRuntimeOrderSimd2xmm[coulombIndex][vdwkt];
}

static NbnxmKernelFunc* selectNbnxmKernelEnerEspSimd2xmm(const int coulkt,
                                                         const int vdwkt,
                                                         const int forceOrder,
                                                         const int energyOrder)
{
    const int coulombIndex = nbnxmEspAnalyticalCoulombKernelIndex2xmm(coulkt);
    if (coulombIndex < 0)
    {
        return nbnxmKernelEnerSimd2xmm[coulkt][vdwkt];
    }
    const int pairIndex = nbnxmEspNearDiagonalOrderPairIndex2xmm(forceOrder, energyOrder);
    if (pairIndex >= 0)
    {
        return nbnxmKernelEnerEspNearDiagonalOrderPairSimd2xmm[coulombIndex][pairIndex][vdwkt];
    }
    if (energyOrder >= c_nbnxmEspSpecializedEnergyOrderMin2xmm
        && energyOrder <= c_nbnxmEspSpecializedEnergyOrderMax2xmm)
    {
        return nbnxmKernelEnerEspEnergyOrderSimd2xmm[coulombIndex][energyOrder - c_nbnxmEspSpecializedEnergyOrderMin2xmm][vdwkt];
    }
    return nbnxmKernelEnerEspRuntimeOrderSimd2xmm[coulombIndex][vdwkt];
}

static NbnxmKernelFunc* selectNbnxmKernelEnergrpEspSimd2xmm(const int coulkt,
                                                            const int vdwkt,
                                                            const int forceOrder,
                                                            const int energyOrder)
{
    const int coulombIndex = nbnxmEspAnalyticalCoulombKernelIndex2xmm(coulkt);
    if (coulombIndex < 0)
    {
        return nbnxmKernelEnergrpSimd2xmm[coulkt][vdwkt];
    }
    const int pairIndex = nbnxmEspNearDiagonalOrderPairIndex2xmm(forceOrder, energyOrder);
    if (pairIndex >= 0)
    {
        return nbnxmKernelEnergrpEspNearDiagonalOrderPairSimd2xmm[coulombIndex][pairIndex][vdwkt];
    }
    if (energyOrder >= c_nbnxmEspSpecializedEnergyOrderMin2xmm
        && energyOrder <= c_nbnxmEspSpecializedEnergyOrderMax2xmm)
    {
        return nbnxmKernelEnergrpEspEnergyOrderSimd2xmm[coulombIndex][energyOrder - c_nbnxmEspSpecializedEnergyOrderMin2xmm]
                                                       [vdwkt];
    }
    return nbnxmKernelEnergrpEspRuntimeOrderSimd2xmm[coulombIndex][vdwkt];
}


